fn is_smaller(arr1: &Vec<i32>, arr2: &Vec<i32>) -> bool {
    // Requires: arr1 and arr2 are non-null references to vectors of i32
    // Ensures: Returns true if all elements in arr1 are greater than the corresponding elements in arr2,
    //          or if both arrays are empty. Returns false otherwise.
    // Decreases: The length of the shorter of the two arrays, ensuring termination.
    // Invariant: At any point in the loop, if we have compared n elements, 
    //            then all compared elements in arr1 are greater than those in arr2.
    
    // Check if both arrays are empty
    if arr1.is_empty() && arr2.is_empty() {
        return true;
    }
    
    // Iterate through the arrays and compare elements
    let len1 = arr1.len();
    let len2 = arr2.len();
    let min_len = if len1 < len2 { len1 } else { len2 };

    // Loop invariant: For all indices i < n, arr1[i] > arr2[i] holds true
    // where n is the number of iterations completed.
    let mut i = 0;
    while i < min_len {
        // Assert: i < arr1.len() and i < arr2.len() (since we are iterating up to min_len)
        assert!(i < len1);
        assert!(i < len2);
        
        // Compare elements
        if arr1[i] <= arr2[i] {
            return false; // Return false if any element in arr1 is not greater than the corresponding element in arr2
        }
        
        i += 1; // Increment the index
    }
    
    true // Return true if all elements in arr1 are greater than those in arr2
}